// Adventure-only ownership/reservation adapter. Bare lab URLs remain unchanged practice.
import {playerStore} from './player-store.js';
import {experimentByFile} from './experiment-definitions.js';
import {apparatusAccess,completeAttempt} from './progression.js';
const adventure=()=>typeof window!=='undefined'&&new URL(location.href).searchParams.get('adventure')==='1';
let current=null,submitted=new Set();
function definition(){return experimentByFile(location.pathname.split('/').at(-1)||'index.html');}
function bar(message=''){if(!adventure())return;let b=document.getElementById('adventure-lab-bar');if(!b){const link=document.createElement('link');link.rel='stylesheet';link.href='adventure-lab.css';document.head.append(link);b=document.createElement('nav');b.id='adventure-lab-bar';b.setAttribute('aria-label','Your adventure');b.innerHTML='<a href="adventure.html">← Town</a><a href="adventure.html?panel=map">Progression map</a><span id="adventure-lab-name"></span><span id="adventure-lab-status" role="status"></span>';document.body.prepend(b);}const p=playerStore.load().player;document.getElementById('adventure-lab-name').textContent=p?p.name+' · '+p.currency+' Lab credits':'Adventure profile required';document.getElementById('adventure-lab-status').textContent=message;const back=document.getElementById('return-laboratory');if(back)back.href='laboratory.html?adventure=1';}
function block(message){queueMicrotask(()=>{bar(message);let b=document.getElementById('adventure-lab-block');if(!b){b=document.createElement('section');b.id='adventure-lab-block';b.setAttribute('role','alert');b.innerHTML='<div><h1>Laboratory requirements</h1><p></p><a href="adventure.html?panel=map">View your equipment and supplies</a><a id="practice-link">Open separate laboratory practice</a></div>';b.querySelector('#practice-link').href=location.pathname;document.body.append(b);}b.querySelector('p').textContent=message;});}
export function prepareAdventureState(state){if(!adventure())return state;const e=definition(),loaded=playerStore.load(),p=loaded.player,a=e&&p?.attempts[e.id];let reason='';if(!p)reason=loaded.error||'Start or resume an adventure first.';else if(!a||!['active','completed'].includes(a.status))reason='Start this experiment from the laboratory room or progression map to reserve its supplies.';else if(Object.entries(e.equipment).some(([id,n])=>(p.equipment[id]||0)<n))reason='Required reusable equipment is missing. Visit the equipment shop.';else if(Object.entries(e.materials).some(([id,n])=>(a.supplies[id]||0)<n))reason='This attempt has no valid supply reservation.';if(reason){state.phase='blocked';for(const o of Object.values(state.items)){o.stored=true;o.adventureUnavailable=true;if('on'in o)o.on=false;}block(reason);return state;}const access=apparatusAccess(p,e,a);for(const [id,o]of Object.entries(state.items)){o.adventureUnavailable=!access[id];if(!access[id]){o.stored=true;if('on'in o)o.on=false;}}current={state,definition:e,attemptId:a.id};queueMicrotask(()=>{document.getElementById('adventure-lab-block')?.remove();bar(a.status==='completed'?'Replaying your reserved attempt. Completion is already recorded.':'Supplies reserved · progress saves after the existing review.');});return state;}
if(typeof document!=='undefined'){
 document.addEventListener('chemtopia:experiment-completed',async event=>{if(!adventure()||!current||current.definition.id!==event.detail?.lab||submitted.has(current.attemptId))return;const {definition:e,attemptId}=current;submitted.add(attemptId);try{const saved=await playerStore.transact(p=>completeAttempt(p,e.id,attemptId));bar(saved.result?'Experiment completion saved locally.':'This attempt has already completed or was replaced. Return to town to check progress.');}catch(err){submitted.delete(attemptId);bar(err.message);}});
 window.addEventListener('storage',()=>{if(!adventure()||!current)return;const p=playerStore.load().player;if(!p){block('The local profile changed. Return to town.');return;}const a=p.attempts[current.definition.id];if(!a||a.id!==current.attemptId){block('A different adventure attempt replaced this one. Return to town.');return;}const access=apparatusAccess(p,current.definition,a);for(const [id,o]of Object.entries(current.state.items))o.adventureUnavailable=!access[id];bar('Inventory refreshed from your local profile.');});
}
